import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Deposit } from '../components/Deposit';

import styles from './Demo.module.css';
import { Tracker } from '../components/Tracker/Tracker';
import { Strategys } from '../components/Strategys';
import { AccountModal } from '../components/AccountModal/AccountModal';
import { AccountInformation } from '../components/AccountInformation';
import { useSelector } from 'react-redux';

export const Demo = () => {
  const [showModal, setShowModal] = useState(false);
  const [accountNumber, setAccountNumber] = useState('');
  const userData = useSelector((state) => state.userData?.data);

  useEffect(() => {
    if (!userData) {
      // Можно выбрать: показать модалку или просто ничего не делать
      setShowModal(true);
      return;
    }

    if (!userData.demoAccountNumber) {
      setShowModal(true);
    } else {
      setAccountNumber(userData.demoAccountNumber);
    }
  }, []);

  const handleSaveAccount = (number) => {
    setAccountNumber(number);
    localStorage.setItem('demoAccountNumber', number);
    setShowModal(false);
  };

  const handleCloseModal = () => {
    setShowModal(false);
  };

  const handleSettingsClick = () => {
    setShowModal(true); // Открываем модал по кнопке "настроить"
  };

  return (
    <>
      {showModal && (
        <AccountModal
          title={'Демо-счет'}
          description={
            'При помощи демо-счета Вы сможете убедиться в эффективности работы нашей ИИ-системы. Чтобы начать демо торговлю введите номер демо-счета. Если у Вас еще нет номера — создайте демо счет'
          }
          inputField={true}
          placeholder={'Введите номер демо-счёта'}
          firstButton={'Готово'}
          secondButton={'Создать демо-счёт'}
          onSave={handleSaveAccount}
          onClose={handleCloseModal}
          numberName={'demoAccountNumber'}
          accountType={'demo'}
        />
      )}

      <div style={{ filter: showModal ? 'blur(3px)' : 'none' }}>
        <div className={styles.header}>
          <h1 className={styles.title}>Демо-счёт</h1>
          <AccountInformation
            onSettingsClick={handleSettingsClick}
            accountNumber={accountNumber}
            accountName={'demoAccountNumber'}
          />
        </div>
        <Deposit statistics={true} cssVariant="alt" />
        <Tracker />
        <Strategys />
      </div>
    </>
  );
};
