import React, { useState } from 'react';
import styles from './Reports.module.css';
import { DateRangePicker } from '../DateRangePicker/DateRangePicker';

export const Reports = () => {
  const [selectedDates, setSelectedDates] = useState({ startDate: null, endDate: null });
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [modalContent, setModalContent] = useState('');

  const handleDateChange = ({ startDate, endDate }) => {
    setSelectedDates({ startDate, endDate });
    console.log('Выбранный диапазон:', startDate, '—', endDate);
  };

  const openModal = (content) => {
    setModalContent(content);
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
    setModalContent('');
  };

  const downloadPDF = () => {
    openModal('Скачивание отчёта в формате PDF...');
    setTimeout(() => {
      setModalContent('Отчёт загружен!');
      setTimeout(closeModal, 2000);
    }, 1500);
  };

  return (
    <div className={styles.container}>
      <div className={styles.header}>
        <h2 className={styles.tytle}>Отчёты</h2>
      </div>
      <div className={styles.creation}>
        <div className={styles.period}>
          <div className={styles.label}>Период:</div>
          <DateRangePicker onChange={handleDateChange} />
        </div>
        <div className={styles.getReport}>
          <button className={styles.look} onClick={() => openModal('Здесь будет просмотр отчёта')}>
            Смотреть
          </button>
          <button className={styles.download} onClick={downloadPDF}>
            Скачать .pdf
          </button>
        </div>
      </div>

      {isModalOpen && (
        <div className={styles.modalOverlay}>
          <div className={styles.modal}>
            <p>{modalContent}</p>
            <button className={styles.closeButton} onClick={closeModal}>
              Закрыть
            </button>
          </div>
        </div>
      )}
    </div>
  );
};
