import styles from './GradientBorderBox.module.css';

export const GradientBorderBox = ({
  children,
  borderRadius = 20,
  borderWidth = 2,
  gradient = 'linear-gradient(160.57deg, #413988 -32.35%, #CFDCF9 -4.55%, #231C83 70.91%)',
  style = {},
  className = '',
  ...rest
}) => (
  <div
    className={`${styles.gradientBorderBox} ${className}`}
    style={{
      '--gbb-radius': typeof borderRadius === 'number' ? `${borderRadius}px` : borderRadius,
      '--gbb-width': typeof borderWidth === 'number' ? `${borderWidth}px` : borderWidth,
      '--gbb-gradient': gradient,
      ...style,
    }}
    {...rest}
  >
    <span className={styles.gradientBorder} aria-hidden="true" />
    <div className={styles.gradientBorderContent}>
      {children}
    </div>
  </div>
);