/**
 * Вычисляет адаптивное значение на основе линейной зависимости.
 *
 * @param {Object} params - Параметры функции.
 * @param {number} params.value - Текущее значение (например, ширина или высота экрана).
 * @param {number} [params.base=0] - Базовое значение результата при baseValue.
 * @param {number} [params.baseValue=0] - Значение value, при котором результат равен base.
 * @param {number} [params.min] - Минимальное значение результата (по умолчанию base).
 * @param {number} [params.max] - Максимальное значение результата (по умолчанию Infinity).
 * @param {number} [params.k=1] - Коэффициент линейного роста.
 * @returns {number} Адаптивное значение с учётом ограничений.
 *
 * @example
 * // Для ширины экрана:
 * getAdaptiveLength({ value: window.innerWidth, base: 100, baseValue: 1024, k: 0.5, min: 100, max: 500 });
 */
export const getAdaptiveLength = ({
  value,
  base = 0,
  baseValue = 0,
  min,
  max,
  k = 1,
}) => {
  const len = base + (value - baseValue) * k;
  const minValue = min !== undefined ? min : base;
  const maxValue = max !== undefined ? max : Infinity;
  return Math.max(minValue, Math.min(len, maxValue));
};