import { useState } from 'react';
import styles from './AccountModal.module.css';
import { useDispatch, useSelector } from 'react-redux';
import { saveAccountNumberRequest } from '../../../../../redux/slices/userDataSlice';

export const AccountModal = ({
  title,
  description,
  inputField,
  placeholder,
  firstButton,
  secondButton,
  onSave,
  onClose,
  numberName,
  accountType,
}) => {
  const [accountNumber, setAccountNumber] = useState('');
  const dispatch = useDispatch();
  const userId = useSelector((state) => state.login?.user.id);
  //const userId = useSelector((state) => state.auth.user?.id); переделать вот так

  const handleSave = () => {
    const trimmedAccountNumber = accountNumber.trim();

    localStorage.setItem(numberName, trimmedAccountNumber);

    onSave(trimmedAccountNumber);

    // Закрываем модальное окно
    onClose();

    if (userId) {
      dispatch(
        saveAccountNumberRequest({
          userId,
          accountNumber: trimmedAccountNumber,
          accountType, // "demo" или "real"
        }),
      );
    }
  };

  const handleRedirect = (accountType) => {
    if (accountType === 'demo') {
      window.open('https://my.roboforex.com/en/trading-account/open-demo-account/', '_blank');
      console.log('demo');
    }
    if (accountType === 'real') {
      window.open('https://my.roboforex.com/en/trading-account/open-trading-account/', '_blank');
      console.log('real');
    }
  };

  const handleAccountNumberChange = (e) => {
    const onlyDigits = e.target.value.replace(/\D/g, '');
    setAccountNumber(onlyDigits);
  };

  return (
    <div className={styles.overlay}>
      <div className={styles.modal}>
        <button className={styles.closeButton} onClick={onClose}>
          <svg
            width="42"
            height="42"
            viewBox="0 0 24 24"
            fill="none"
            stroke="white"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            <line x1="18" y1="6" x2="6" y2="18" />
            <line x1="6" y1="6" x2="18" y2="18" />
          </svg>
        </button>

        <h3 className={styles.title}>{title}</h3>
        <span className={styles.description}>{description}</span>
        {inputField ? (
          <input
            type="text"
            maxlength={20}
            value={accountNumber}
            onChange={handleAccountNumberChange}
            placeholder={placeholder}
          />
        ) : null}
        <div className={styles.buttonBlock}>
          <button className={styles.doneButton} onClick={handleSave}>
            {firstButton}
          </button>
          <button className={styles.createButton} onClick={() => handleRedirect(accountType)}>
            <span>{secondButton}</span>
          </button>
        </div>
      </div>
    </div>
  );
};
