import React, { useState, useEffect, useRef, useMemo } from 'react';
import { AnimatedLines } from './AnimatedLines';
import { BinaryRain } from './BinaryRain';
import styles from './Strategies.module.css';

/**
 * Объект стилизации карточек по их ID.
 * Используется для определения:
 * - положения центра трансформации (transformOrigin),
 * - padding для текстовой области,
 * - скругления углов (borderRadius),
 * - масштабирования и позиционирования при hover-анимации.
 *
 * Ключами являются идентификаторы карточек (1–5).
 */
const cardStyleMap = {
  1: {
    transformOrigin: 'left top',
    padding: {
      paddingTop: '0.0vw',
      paddingRight: '0.0vw',
      paddingBottom: '0.0vw',
      paddingLeft: '0.0vw',
    },
    borderRadius: {
      borderTopLeftRadius: '1.4vw',
      borderTopRightRadius: '0.7vw',
      borderBottomRightRadius: '0.7vw',
      borderBottomLeftRadius: '0.7vw',
    },
    transform: 'scaleX(3) translateX(-0.07vw) scaleY(3) translateY(-0.07vw)',
  },
  2: {
    transformOrigin: 'right top',
    padding: {
      paddingTop: '0.0vw',
      paddingRight: '0.0vw',
      paddingBottom: '0.0vw',
      paddingLeft: '0.0vw',
    },
    borderRadius: {
      borderTopLeftRadius: '0.7vw',
      borderTopRightRadius: '1.4vw',
      borderBottomRightRadius: '0.7vw',
      borderBottomLeftRadius: '0.7vw',
    },
    transform: 'scaleX(3) translateX(0.07vw) scaleY(3) translateY(-0.07vw)',
  },
  3: {
    transformOrigin: 'right top',
    padding: {
      paddingTop: '0.0vw',
      paddingRight: '0.0vw',
      paddingBottom: '0.0vw',
      paddingLeft: '0.0vw',
    },
    borderRadius: {
      borderTopLeftRadius: '0.7vw',
      borderTopRightRadius: '1.4vw',
      borderBottomRightRadius: '0.7vw',
      borderBottomLeftRadius: '0.7vw',
    },
    transform: 'scaleX(3) translateX(0.07vw) scaleY(3) translateY(-0.07vw)',
  },
  4: {
    transformOrigin: 'left top',
    padding: {
      paddingTop: '0.0vw',
      paddingRight: '0.0vw',
      paddingBottom: '0.0vw',
      paddingLeft: '0.0vw',
    },
    borderRadius: {
      borderTopLeftRadius: '1.4vw',
      borderTopRightRadius: '0.7vw',
      borderBottomRightRadius: '0.7vw',
      borderBottomLeftRadius: '0.7vw',
    },
    transform: 'scaleX(3) translateX(-0.07vw) scaleY(3) translateY(-0.07vw)',
  },
  5: {
    transformOrigin: 'left top',
    padding: {
      paddingTop: '0.0vw',
      paddingRight: '0.0vw',
      paddingBottom: '0.0vw',
      paddingLeft: '0.0vw',
    },
    borderRadius: {
      borderTopLeftRadius: '1.4vw',
      borderTopRightRadius: '0.7vw',
      borderBottomRightRadius: '0.7vw',
      borderBottomLeftRadius: '0.7vw',
    },
    transform: 'scaleX(3) translateX(-0.07vw) scaleY(3) translateY(-0.07vw)',
  },
};

/**
 * Стили, применяемые по умолчанию, если не найден соответствующий ID карточки.
 */
const defaultStyle = {
  transformOrigin: 'center center',
  padding: { padding: '2vw' },
  borderRadius: {
    borderTopLeftRadius: '1vw',
    borderTopRightRadius: '1vw',
    borderBottomRightRadius: '1vw',
    borderBottomLeftRadius: '1vw',
  },
  transform: 'scaleX(3) translateX(-0.12vw) scaleY(3) translateY(-0.12vw)',
};

/**
 * @typedef {Object} CardStyle
 * @property {string} transformOrigin - Точка трансформации для анимации (например: 'left top', 'center center')
 * @property {Object} padding - CSS-отступы для текстовой области
 * @property {string} [padding.paddingTop]
 * @property {string} [padding.paddingRight]
 * @property {string} [padding.paddingBottom]
 * @property {string} [padding.paddingLeft]
 * @property {Object} borderRadius - Скругления по углам
 * @property {string} [borderRadius.borderTopLeftRadius]
 * @property {string} [borderRadius.borderTopRightRadius]
 * @property {string} [borderRadius.borderBottomRightRadius]
 * @property {string} [borderRadius.borderBottomLeftRadius]
 * @property {string} transform - CSS-преобразование при ховере (масштаб, перемещение)
 */

export const Strategies = () => {
  const centerRef = useRef(null);
  const cardRefs = useRef({});
  const containerRef = useRef(null);
  const openTimeout = useRef(null);

  const [openedCardId, setOpenedCardId] = useState(null);
  const [linePositions, setLinePositions] = useState([]);
  const [hoveredCardId, setHoveredCardId] = useState(null);
  const [closingCardId, setClosingCardId] = useState(null);

  const inDevelopment = {
    frontLabel: 'ТС: в разработке',
    description:
      'Стратегия с помощью ИИ выявляет наиболее волатильный инструмент в рамках торгового дня и просчитывает ряд сделок как на повышение так и на понижение',
  };

  // Данные о карточках
  const cardsData = useMemo(
    () => [
      {
        id: 1,
        frontLabel: 'ОБ30',
        description:
          'Алгоритмическая торговая стратегия разработана с целью поиска точки входа на 1-минутном таймфрейме, позволяя алгоритму ювелирно входить в сделку с увеличенным соотношением risk/reward. В стратегии используется ордерблок, структурный анализ, сетка фибоначчи.',
        position: { x: '-150%', y: '-170%' },
      },
      {
        id: 2,
        frontLabel: 'VSA_ML',
        description:
          'Торговая стратегия разработана с применением машинного обучения и инновационных гибридных моделей нейросети LSTM и Transformer в частности. Для принятия торговых решений модель анализирует профили объемов, зоны ликвидности, выявляет аномальные аномальный объемы. Для усиления трейдов используются индикаторы A/D-line, ATR, RSI.',
        position: { x: '220%', y: '-150%' },
      },
      {
        id: 3,
        frontLabel: 'TSA_ML',
        description:
          'Торговая стратегия разработана с применением машинного обучения и инновационных гибридных моделей, обученных предсказывать направление движения котировки, а также значимые импульсные движения цены актива. Для усиления трейдов используются индикаторы RSI, ADX, MACD, нормализация и логарифмирование цен.',
        position: { x: '300%', y: '120%' },
      },
      {
        id: 4,
        frontLabel: 'Fibo + VSA',
        description: inDevelopment.description,
        position: { x: '-150%', y: '160%' },
      },
      {
        id: 5,
        frontLabel: inDevelopment.frontLabel,
        description: inDevelopment.description,
        position: { x: '-400%', y: '20%' },
      },
    ],
    [],
  );

  const handleMouseOut = () => {
    setHoveredCardId(null);
  };

  const handleMouseEnter = (cardId) => {
    setHoveredCardId(cardId);
    setClosingCardId(null);

    if (openTimeout.current) clearTimeout(openTimeout.current);

    // const delay = getCardOpenDelay(cardId); // вот это должно быть!
    openTimeout.current = setTimeout(() => {
      setOpenedCardId(cardId);
    }, getCardOpenDelay(cardId));
  };

  const handleMouseLeave = (cardId) => {
    setClosingCardId(cardId);
    setHoveredCardId(null);

    if (openTimeout.current) clearTimeout(openTimeout.current);
    setOpenedCardId(null);
  };

  const STOP_COUNT = 50; // или то, что ты передаёшь в AnimatedLines
  const windowSize = 5; // то же, что в AnimatedLines
  const stepDelay = 0.015; // то же, что в AnimatedLines

  const getLineLength = (line) => {
    if (!line) return 0;
    return Math.sqrt(Math.pow(line.x2 - line.x1, 2) + Math.pow(line.y2 - line.y1, 2));
  };

  const maxLineLength = linePositions.length ? Math.max(...linePositions.map(getLineLength)) : 1;

  const getCardOpenDelay = () => {
    return (STOP_COUNT - windowSize) * stepDelay * 1000;
  };

  useEffect(() => {
    const refs = {};
    cardsData.forEach((card) => {
      refs[card.id] = React.createRef();
    });
    cardRefs.current = refs;
  }, []);

  // Очищаем таймер при размонтировании компонента
  useEffect(() => {
    return () => {
      if (openTimeout.current) clearTimeout(openTimeout.current);
    };
  }, []);

  useEffect(() => {
    const updateLines = () => {
      if (!centerRef.current || !containerRef.current) return;

      const containerRect = containerRef.current.getBoundingClientRect();
      const centerRect = centerRef.current.getBoundingClientRect();

      const centerX = centerRect.left - containerRect.left + centerRect.width / 2;
      const centerY = centerRect.top - containerRect.top + centerRect.height / 2;

      const newLines = cardsData.map((card) => {
        const cardEl = cardRefs.current[card.id]?.current;
        if (!cardEl) return null;

        const cardRect = cardEl.getBoundingClientRect();
        const cardX = cardRect.left - containerRect.left + cardRect.width / 2;
        const cardY = cardRect.top - containerRect.top + cardRect.height / 2;

        return {
          id: card.id,
          x1: centerX,
          y1: centerY,
          x2: cardX,
          y2: cardY,
        };
      });

      setLinePositions(newLines.filter(Boolean));
    };

    updateLines();
    window.addEventListener('resize', updateLines);
    window.addEventListener('scroll', updateLines);

    return () => {
      window.removeEventListener('resize', updateLines);
      window.removeEventListener('scroll', updateLines);
    };
  }, [cardsData]);

  return (
    <div className={styles.container}>
      <div className={styles.title}>
        <h1 className={styles.title_text}>Стратегии</h1>
      </div>

      <div ref={containerRef} className={styles.strategiesInfo}>
        <div className={styles.orbit} />
        <AnimatedLines
          lines={linePositions}
          hoveredLineId={hoveredCardId}
          STOP_COUNT={STOP_COUNT}
          windowSize={windowSize}
          stepDelay={stepDelay}
        />
        {cardsData.map((card) => {
          const isOpened = openedCardId === card.id;
          //const isOpened = true;
          const isClosing = closingCardId === card.id;

          const styleInfo = cardStyleMap[card.id] || defaultStyle;

          return (
            <div
              key={card.id}
              ref={cardRefs.current[card.id]}
              className={styles.cardWrapper}
              style={{
                transform: `translate(${card.position.x}, ${card.position.y})`,
                transformOrigin: styleInfo.transformOrigin,
                zIndex: isOpened ? 1000 : 1,
                border: isOpened ? '4px solid transparent' : '4px solid #3D3D3D',
                backgroundColor: isOpened ? '#0F0F0F' : '#1D1D1D',
              }}
              onMouseEnter={() => handleMouseEnter(card.id)}
              onMouseLeave={() => handleMouseLeave(card.id)}
            >
              <div className={styles.cardBackgroundWrapper}>
                {/* Подложка с описанием */}
                <div
                  className={`${styles.cardBackground} ${
                    isOpened
                      ? `${styles.cardBackgroundActive} ${styles.cardBackgroundOpen} ${
                          styles[`shape${card.id}`]
                        }`
                      : isClosing
                      ? `${styles.cardBackgroundActive} ${styles.cardBackgroundClose} ${
                          styles[`shape${card.id}`]
                        }`
                      : ''
                  }`}
                  style={{
                    transformOrigin: styleInfo.transformOrigin,
                    ...(isOpened
                      ? {
                          ...styleInfo.borderRadius,
                          transform: styleInfo.transform,
                        }
                      : isClosing
                      ? {
                          ...styleInfo.borderRadius,
                          transform: 'scale(1)',
                        }
                      : {
                          borderRadius: '50%',
                          transform: 'scale(1)',
                        }),
                  }}
                >
                  <div
                    className={styles.back}
                    style={{
                      ...styleInfo.padding,
                      opacity: isOpened || isClosing ? 1 : 0,
                      transition: '1s ease-in, border-radius 1s ease-in, opacity 1s ease-in',
                      pointerEvents: isOpened ? 'auto' : 'none',
                    }}
                  >
                    <div className={styles.animationBackground}>
                      {/*<video
                        src="/card1-2.gif.mp4" // путь к твоему mp4-файлу
                        autoPlay
                        loop
                        muted
                        playsInline
                        style={{ width: '100%', height: '100%', objectFit: 'cover' }}
                      />*/}
                      <BinaryRain
                        rows={5}
                        length={60}
                        color="#636363ff"
                        speed={40}
                        highlightText="AITrading"
                        highlightColor="#636363ff"
                        fontSize="0.3vw"
                        fontFamily="Roboto"
                        background="transparent"
                      />
                    </div>
                    <span className={styles.description}>{card.description}</span>
                  </div>
                </div>

                {/* Основная карточка — не меняется при ховере */}
                <div className={styles.card}>
                  <div className={styles.front}>
                    <span className={styles.label}>{card.frontLabel}</span>
                  </div>
                </div>
              </div>
            </div>
          );
        })}

        <div
          ref={centerRef}
          className={styles.brainCenter}
          style={{
            boxShadow: hoveredCardId
              ? '0 5px 80px 20px rgba(255, 189, 6, 0.7)' // ярче
              : '0 5px 40px 10px rgba(255, 189, 6, 0.4)', // тусклее
          }}
        >
          <span className={styles.label}>AITrading</span>
        </div>
      </div>
    </div>
  );
};
