import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useDispatch, useSelector } from 'react-redux';
import { fetchLoginRequest } from '../../../../redux/slices/loginSlice';
import { Button } from '../../../../shared/ui/Button';
import {
  GradientBorderBox,
  FormErrorMessage,
  PasswordVisibilityToggle,
} from '../../../../shared/ui';
import { Loading } from '../../../../components/Loading';
import { SlidingWrapper } from '../SlidingWrapper';
import { Register } from '../../ui';
import { useForm, useWatch } from 'react-hook-form';
import { emailValidation, passwordValidation } from '../../../../helpers/validationRules';
import styles from './LoginForm.module.css';

/**
 * Форма входа пользователя.
 *
 * Предоставляет интерфейс для аутентификации с полями email и пароля.
 * Использует Redux для управления состоянием входа, а также
 * отображает индикатор загрузки во время выполнения запроса.
 *
 * После успешного входа:
 * - Пользователь перенаправляется на страницу профиля.
 * - Форма закрывается через вызов `onClose`.
 *
 * Поддерживает:
 * - Показ/скрытие пароля.
 * - Валидацию полей на клиенте.
 * - Плавное открытие формы регистрации через боковую панель.
 * - Доступность: переключатель пароля работает с клавиатуры (Enter/пробел).
 *
 *
 * @param {Object} props - Входные параметры компонента.
 * @param {() => void} props.onClose - Функция, вызываемая после успешного входа
 *                                     для закрытия формы.
 *
 * @component
 * @example
 * <LoginForm onClose={() => setShowForm(false)} />
 *
 * @returns {JSX.Element} Форма входа с возможностью перехода к регистрации.
 *
 * @remarks
 * - Использует Redux для управления состоянием аутентификации.
 * - Показывает индикатор загрузки во время выполнения запроса.
 * - Автоматически перенаправляет на '/profile' при успешном входе.
 * - Поддерживает доступность: переключатель пароля реагирует на Enter и пробел.
 */

export const LoginForm = ({ onClose }) => {
  const { isLoggedIn, isLoading, error: serverError } = useSelector((state) => state.login);
  const [user, setUser] = useState({
    email: '',
    password: '',
  });
  const [showPassword, setShowPassword] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const {
    register,
    handleSubmit,
    setError,
    clearErrors,
    control,
    formState: { errors },
  } = useForm();
  const navigate = useNavigate();
  const dispatch = useDispatch();
  const watch = useWatch({ control });

  useEffect(() => {
    if (serverError) {
      clearErrors(); // очищает все ошибки
    }
  }, [watch.email, watch.password]);

  useEffect(() => {
    if (isLoggedIn) {
      onClose();
      navigate('/profile');
    }
  }, [isLoggedIn]); //navigate

  useEffect(() => {
    if (serverError) {
      setError('email', {
        type: 'server',
        message: serverError,
      });

      setError('password', {
        type: 'server',
        message: serverError,
      });
    }
  }, [serverError, setError]);

  const handleRegisterClick = () => {
    setShowForm(true);
  };

  const onSubmit = (data) => {
    console.log('data', data);
    dispatch(fetchLoginRequest(data));
  };

  console.log(serverError, errors);

  return (
    <>
      {isLoading ? (
        <Loading />
      ) : (
        <div className={styles.wrapper}>
          <div className={styles.container}>
            <h1 className={styles.title}>Вход в личный кабинет</h1>
            <form id="authForm" className={styles.authForm} onSubmit={handleSubmit(onSubmit)}>
              {/* Email */}
              <div className={styles.formGroup}>
                <label htmlFor="email" className={styles.formLabel}>
                  E-mail
                </label>
                <GradientBorderBox gradient="linear-gradient(175.69deg, #000000 43.18%, #FFFFFF 167.22%)">
                  <input
                    type="text"
                    id="email"
                    {...register('email', emailValidation)}
                    className={styles.formInput}
                    placeholder="Введите ваш логин"
                    autoComplete="email"
                  />
                </GradientBorderBox>
                <FormErrorMessage name="email" errors={errors} />
              </div>

              {/* Password */}
              <div className={styles.formGroup}>
                <label htmlFor="password" className={styles.formLabel}>
                  Пароль
                </label>
                <div className={styles.inputContainer}>
                  <GradientBorderBox gradient="linear-gradient(175.69deg, #000000 43.18%, #FFFFFF 167.22%)">
                    <input
                      type={showPassword ? 'text' : 'password'}
                      id="password"
                      {...register('password', passwordValidation)}
                      className={styles.formInput}
                      placeholder="Введите ваш пароль"
                      autoComplete="password"
                      
                    />
                    
                  </GradientBorderBox>

                  {/* Переключатель видимости пароля */}
                  <PasswordVisibilityToggle
                    visible={showPassword}
                    onToggle={() => setShowPassword((v) => !v)}
                  />
                </div>
                <FormErrorMessage name="password" errors={errors} />
              </div>

              {/* Кнопка входа */}
              <Button
                type="submit"
                onClick={() => setShowForm(false)}
                style={{ background: '#147AFF', color: '#EDEDED' }}
              >
                Войти
              </Button>

              {/* Кнопка регистрации */}
              <Button
                type="button"
                style={{ background: '#1D1D1D', color: '#147AFF' }}
                onClick={handleRegisterClick}
              >
                Зарегистрироваться
              </Button>
            </form>
          </div>
        </div>
      )}

      {/* Встроенная форма регистрации через SlidingWrapper */}
      <SlidingWrapper isOpen={showForm} onClose={() => setShowForm(false)}>
        <Register onClose={() => setShowForm(false)} />
      </SlidingWrapper>
    </>
  );
};
