import React, { useEffect, useState, useMemo } from 'react';
import { TrendAreaChart } from '../Charts';
import { TestBlock } from '../TestBlock';

import { mergeProfit } from '../../../../../utils/utils';

import styles from './ProfitabilityChart.module.css';

export const ProfitabilityChart = ({
  strategySelector,
  pageType,
  accountData,
  timeframeSelector,
  viewSelector,
  height,
  additionalData = [],
  benchmarkSelector,
}) => {
  const [closedFromFile, setClosedFromFile] = useState([]);

  useEffect(() => {
    fetch(`/data/${strategySelector}.json`)
      .then((response) => response.json())
      .then((data) => {
        setClosedFromFile(data);
      })
      .catch((error) => {
        console.error(`Ошибка при загрузке ${strategySelector}json:`, error);
      });
  }, [strategySelector]);

  const closed =
    pageType === 'mainPage'
      ? closedFromFile
      : accountData?.data?.accountInfo?.positions_closed || [];

  const opened = accountData?.data?.accountInfo?.positions_opened || [];

  const closedData = closed.map((pos) => ({
    date: new Date(Number(pos.time) * 1000).toLocaleDateString('ru-RU'),
    profit: Number(pos.profit),
    type: 'closed',
  }));

  const openedData = opened.map((pos) => ({
    date: new Date(Number(pos.time_open) * 1000).toLocaleDateString('ru-RU'),
    profit: Number(pos.profit),
    type: 'opened',
  }));

  const allData = [...closedData, ...openedData].sort((a, b) => {
    // Сортируем по timestamp, а не по строке даты!
    const aTime =
      a.type === 'closed'
        ? Number(
            closed.find(
              (p) => new Date(Number(p.time) * 1000).toLocaleDateString('ru-RU') === a.date,
            )?.time,
          )
        : Number(
            opened.find(
              (p) => new Date(Number(p.time_open) * 1000).toLocaleDateString('ru-RU') === a.date,
            )?.time_open,
          );
    const bTime =
      b.type === 'closed'
        ? Number(
            closed.find(
              (p) => new Date(Number(p.time) * 1000).toLocaleDateString('ru-RU') === b.date,
            )?.time,
          )
        : Number(
            opened.find(
              (p) => new Date(Number(p.time_open) * 1000).toLocaleDateString('ru-RU') === b.date,
            )?.time_open,
          );
    return aTime - bTime;
  });

  // === ФИЛЬТРАЦИЯ ПО ТАЙМФРЕЙМУ С АВТОМАТИЧЕСКИМ РАСШИРЕНИЕМ ===
  const timeframeMap = {
    День: 1,
    Неделя: 7,
    Месяц: 30,
    '6 Месяцев': 182,
    Год: 365,
  };
  const now = new Date();
  const maxDays = 365 * 5; // максимум 5 лет
  let days = timeframeMap[timeframeSelector] || 365;
  let filteredData = [];

  while (days <= maxDays) {
    const fromDate = new Date(now.getTime() - days * 24 * 60 * 60 * 1000);
    filteredData = allData.filter((item) => {
      const [day, month, year] = item.date.split('.');
      const itemDate = new Date(`${year}-${month}-${day}`);
      return itemDate >= fromDate;
    });
    if (filteredData.length > 0) break;
    days++; // увеличиваем период на 1 день
  }

  // === КУМУЛЯТИВНЫЙ ПРОФИТ ===
  /*let cumulative = 0;
let data = filteredData.map(item => {
  cumulative += item.profit;
  return {
    date: item.date,
    profit: cumulative,
    type: item.type
  };
});

const initialBalance = 3280; // Стартовая сумма
let cumulativeProfit = 0;

let data = filteredData.map(item => {
  cumulativeProfit += item.profit;
  const percentProfit = (cumulativeProfit / initialBalance) * 100;
  
  return {
    date: item.date,
    profit: +percentProfit.toFixed(2), // округление до 2 знаков
    type: item.type
  };
});*/
  const initialBalance = 3280; // Стартовая сумма

  let data = [];

  if (strategySelector === 'VSA_ML') {
    let cumulativeProfit = 0;
    data = filteredData.map((item) => {
      cumulativeProfit += item.profit;
      const percentProfit = (cumulativeProfit / initialBalance) * 100;

      return {
        date: item.date,
        profit: +percentProfit.toFixed(2), // округление до 2 знаков
        type: item.type,
      };
    });
  } else {
    let cumulative = 0;
    data = filteredData.map((item) => {
      cumulative += item.profit;

      return {
        date: item.date,
        profit: +cumulative.toFixed(2), // просто абсолютная сумма
        type: item.type,
      };
    });
  }

  const filterByTimeframe = (dataArray, timeframeSelector) => {
    const timeframeMap = {
      День: 1,
      Неделя: 7,
      Месяц: 30,
      '6 Месяцев': 182,
      Год: 365,
    };

    const now = new Date();
    const maxDays = 365 * 5; // максимум 5 лет
    let days = timeframeMap[timeframeSelector] || 365;
    let result = [];

    while (days <= maxDays) {
      const fromDate = new Date(now.getTime() - days * 24 * 60 * 60 * 1000);
      result = dataArray.filter((item) => {
        const [day, month, year] = item.date.split('.');
        const itemDate = new Date(`${year}-${month}-${day}`);
        return itemDate >= fromDate;
      });

      if (result.length > 0) break;
      days++; // постепенно расширяем период
    }

    return result;
  };

  const [filteredAdditional, setFilteredAdditional] = useState([]);

  useEffect(() => {
    if (Array.isArray(additionalData) && additionalData.length > 0 && timeframeSelector) {
      const filtered = filterByTimeframe(additionalData, timeframeSelector);
      setFilteredAdditional(filtered);
    }

    if (benchmarkSelector === '-' || strategySelector !== 'VSA_ML') {
      setFilteredAdditional([]);
    }
  }, [benchmarkSelector, additionalData, timeframeSelector, strategySelector]);

  if (filteredAdditional) {
    data = mergeProfit(data, filteredAdditional);

    if (data.length > 0) {
      const baseBTC = data[0].profitBTC;

      data = data.map((entry) => {
        const percentChange = ((entry.profitBTC - baseBTC) / baseBTC) * 100;
        return {
          ...entry,
          profitBTC: +percentChange.toFixed(2), // или `${percentChange.toFixed(2)}%` если нужен процент как строка
        };
      });
    }
  }

  console.log('strategySelector', strategySelector, viewSelector);

  const renderActiveView = () => {
    switch (viewSelector) {
      case 'График':
        return <TrendAreaChart data={data} height={height} strategySelector={strategySelector} />;
      case 'Список':
        return <TestBlock accountData={accountData} timeframeSelector={timeframeSelector} />;
      default:
        return <TrendAreaChart data={data} height={height} strategySelector={strategySelector} />;
    }
  };

  return <div className={styles.container}>{renderActiveView()}</div>;
};
